// מדריך טעינת התוסף לכרום – נטען מ-index.html כשנכנסים לכתובת עם #install בסוף
window.KP_GUIDE = "<!doctype html>\n<html lang=\"he\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>טעינת תוסף לכרום</title>\n<meta name=\"claude:viewport-fit-sides\" content=\"cover\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Rubik:wght@500;600;700&family=Heebo:wght@400;500;700&family=JetBrains+Mono:wght@400;500&display=swap\">\n<style>\n/* פריסה: עמודת קריאה אחת; כל שלב = טקסט קצר + המחשת מסך מצוירת עם סימון של איפה ללחוץ. מתג ווינדוס 11/10 משנה רק את ההמחשות שבאמת שונות */\n:root {\n  --bg: #f4f6fb;\n  --paper: #ffffff;\n  --ink: #18202f;\n  --muted: #5b6577;\n  --line: #dfe4ee;\n  --accent: #1f5bd8;\n  --accent-soft: #e3ebfd;\n  --mark: #ff7a1a;\n  --ok: #157f46;\n  --ok-soft: #dcf3e5;\n  --warn-soft: #fff3d6;\n  --warn-ink: #7a4b00;\n  --screen: #eef1f7;\n  --screen-2: #ffffff;\n  --screen-ink: #263043;\n  --screen-line: #d5dbe7;\n  --menu: #ffffff;\n  --f-display: \"Rubik\", \"Heebo\", \"Arial Hebrew\", Arial, sans-serif;\n  --f-body: \"Heebo\", \"Segoe UI\", \"Arial Hebrew\", Arial, sans-serif;\n  --f-mono: \"JetBrains Mono\", Consolas, monospace;\n}\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme=\"light\"]) {\n    --bg: #0f1420; --paper: #171e2d; --ink: #e8ecf5; --muted: #9ba6bb; --line: #2a3448;\n    --accent: #7ea2ff; --accent-soft: #1f2c4a; --mark: #ff9a4d; --ok: #5fd197; --ok-soft: #173326;\n    --warn-soft: #3a2f14; --warn-ink: #ffd27a; --screen: #212a3b; --screen-2: #2a3448; --screen-ink: #dfe5f1; --screen-line: #3a4660; --menu: #2f3a50;\n    color-scheme: dark;\n  }\n}\n:root[data-theme=\"dark\"] {\n  --bg: #0f1420; --paper: #171e2d; --ink: #e8ecf5; --muted: #9ba6bb; --line: #2a3448;\n  --accent: #7ea2ff; --accent-soft: #1f2c4a; --mark: #ff9a4d; --ok: #5fd197; --ok-soft: #173326;\n  --warn-soft: #3a2f14; --warn-ink: #ffd27a; --screen: #212a3b; --screen-2: #2a3448; --screen-ink: #dfe5f1; --screen-line: #3a4660; --menu: #2f3a50;\n  color-scheme: dark;\n}\n* { box-sizing: border-box; }\nbody {\n  margin: 0; background: var(--bg); color: var(--ink); font: 17px/1.65 var(--f-body);\n  padding-block: 0 64px;\n  padding-left: max(16px, env(safe-area-inset-left, 0px));\n  padding-right: max(16px, env(safe-area-inset-right, 0px));\n}\n.wrap { max-width: 860px; margin: 0 auto; }\nh1, h2, h3 { font-family: var(--f-display); margin: 0; text-wrap: balance; line-height: 1.25; }\np { margin: 0; }\ncode, .path { font-family: var(--f-mono); font-size: .88em; direction: ltr; unicode-bidi: isolate; background: var(--accent-soft); color: var(--ink); padding: 1px 7px; border-radius: 6px; }\n:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }\n\n/* כותרת */\n.hero { padding-block: 40px 22px; display: grid; gap: 14px; }\n.hero .tag { font-size: 13px; letter-spacing: .06em; color: var(--accent); font-weight: 700; }\n.hero h1 { font-size: clamp(30px, 6vw, 44px); }\n.hero p { color: var(--muted); max-width: 62ch; }\n.meta { display: flex; gap: 10px; flex-wrap: wrap; }\n.pill { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 12px; border-radius: 99px; background: var(--paper); border: 1px solid var(--line); font-size: 14px; color: var(--muted); }\n\n/* בורר ווינדוס */\n.picker { position: sticky; top: env(safe-area-inset-top, 0px); z-index: 5; background: var(--bg); padding-block: 10px; display: flex; gap: 12px; align-items: center; flex-wrap: wrap; border-bottom: 1px solid var(--line); margin-bottom: 8px; }\nbody::before { content: \"\"; position: fixed; inset: 0 0 auto; height: env(safe-area-inset-top, 0px); z-index: 10; background: var(--bg); }\n.picker span { font-weight: 600; font-size: 15px; }\n.seg { display: inline-flex; background: var(--paper); border: 1px solid var(--line); border-radius: 12px; padding: 4px; gap: 4px; }\n.seg button { border: 0; background: transparent; color: var(--muted); font: 600 15px var(--f-body); padding: 8px 16px; border-radius: 9px; cursor: pointer; }\n.seg button[aria-pressed=\"true\"] { background: var(--accent); color: #fff; }\n.picker small { color: var(--muted); font-size: 13px; }\n\n/* שלבים */\n.step { display: grid; grid-template-columns: 52px minmax(0, 1fr); gap: 18px; padding-block: 30px; border-bottom: 1px solid var(--line); }\n.step:last-of-type { border-bottom: 0; }\n.num { width: 44px; height: 44px; border-radius: 50%; background: var(--accent); color: #fff; font: 700 20px var(--f-display); display: grid; place-items: center; }\n.step h2 { font-size: 23px; margin-bottom: 8px; }\n.step .body { min-width: 0; display: grid; gap: 14px; }\n.step ol, .step ul { margin: 0; padding-inline-start: 22px; display: grid; gap: 6px; }\n.say { font-weight: 700; background: var(--accent-soft); border-radius: 6px; padding: 0 6px; white-space: nowrap; }\n.note { border-radius: 12px; padding: 12px 16px; font-size: 15px; display: flex; gap: 10px; align-items: flex-start; }\n.note.tip { background: var(--ok-soft); }\n.note.warn { background: var(--warn-soft); color: var(--warn-ink); }\n.note b { white-space: nowrap; }\n.copyrow { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }\n.copyrow code { font-size: 17px; padding: 6px 12px; }\n.copybtn { border: 1px solid var(--line); background: var(--paper); color: var(--ink); font: 600 14px var(--f-body); padding: 7px 14px; border-radius: 9px; cursor: pointer; }\n.copybtn:hover { border-color: var(--accent); }\n\n\n/* ---------- צילומי מסך עם סימון ---------- */\nfigure { margin: 0; }\nfigcaption { font-size: 14px; color: var(--muted); margin-top: 8px; }\n.shot { position: relative; border-radius: 12px; overflow: hidden; border: 1px solid var(--line); background: #fff; box-shadow: 0 2px 10px rgba(10, 20, 40, .08); }\n.shot img { display: block; width: 100%; height: auto; }\n.mk { position: absolute; border: 3px solid var(--mark); border-radius: 8px; box-shadow: 0 0 0 3px color-mix(in srgb, var(--mark) 25%, transparent); pointer-events: none; }\n.mk b { position: absolute; top: 50%; inset-inline-end: calc(100% + 6px); transform: translateY(-50%); width: 26px; height: 26px; border-radius: 50%; background: var(--mark); color: #fff; font: 700 14px var(--f-display); display: grid; place-items: center; box-shadow: 0 1px 4px rgba(0,0,0,.3); }\n.mk.at-end b { inset-inline-end: auto; inset-inline-start: calc(100% + 6px); }\n@media (prefers-reduced-motion: no-preference) {\n  .mk { animation: pulse 1.8s ease-in-out infinite; }\n  @keyframes pulse { 50% { box-shadow: 0 0 0 7px color-mix(in srgb, var(--mark) 0%, transparent); } }\n}\n.pair { display: grid; gap: 14px; }\n.step h3 { font-size: 18px; margin-top: 6px; }\n\n/* ווינדוס – הצגת המחשה לפי הבחירה */\n[data-os=\"11\"] .only10, [data-os=\"10\"] .only11 { display: none; }\n\n/* תקלות ועדכון */\n.box { background: var(--paper); border: 1px solid var(--line); border-radius: 16px; padding: 22px; display: grid; gap: 14px; margin-top: 30px; }\n.box h2 { font-size: 22px; }\n.faq { display: grid; gap: 8px; }\n.faq details { border: 1px solid var(--line); border-radius: 12px; padding: 0 16px; background: var(--paper); }\n.faq summary { cursor: pointer; padding: 12px 0; font-weight: 700; }\n.faq details p { padding-bottom: 14px; color: var(--muted); }\n.done { text-align: center; padding-block: 34px 0; color: var(--muted); font-size: 15px; }\n\n\n@media (max-width: 560px) {\n  body { font-size: 16px; }\n  .step { grid-template-columns: 1fr; gap: 10px; }\n  .num { width: 38px; height: 38px; font-size: 17px; }\n  .pair { grid-template-columns: 1fr; }\n  .mk b { width: 20px; height: 20px; font-size: 12px; }\n}\n.note.demo{margin:14px 0 0;background:var(--warn-soft);color:var(--warn-ink)}\n</style>\n</head>\n<body>\n\n<div class=\"wrap\" dir=\"rtl\" lang=\"he\" data-os=\"11\" id=\"root\">\n  <header class=\"hero\">\n    <div class=\"tag\">מדריך התקנה</div>\n    <h1>טעינת תוסף לכרום מקובץ</h1>\n    <p>תוסף שקיבלת כקובץ ZIP, ולא מחנות האינטרנט של כרום, נטען דרך \"מצב פיתוח\". זה נשמע טכני, אבל אלה שישה צעדים קצרים, ועושים אותם פעם אחת. כל הצילומים כאן אמיתיים, והמסגרת הכתומה מראה איפה ללחוץ.</p>\n    <div class=\"note demo\" role=\"note\"><span>🖼️</span><span><b>הצילומים להדגמה בלבד.</b> הם צולמו בגרסה ישנה של התוסף, ולכן שם התוסף, מספר הגרסה ושמות הקבצים אצלך יכולים להיראות קצת אחרת. השלבים עצמם זהים.</span></div>\n    <div class=\"meta\"><span class=\"pill\">⏱ בערך 3 דקות</span><span class=\"pill\">💻 מחשב עם ווינדוס וכרום</span><span class=\"pill\">📦 קובץ התוסף (ZIP)</span></div>\n  </header>\n\n  <div class=\"picker\" role=\"group\" aria-label=\"גרסת ווינדוס\">\n    <span>איזה ווינדוס יש לך?</span>\n    <div class=\"seg\"><button type=\"button\" data-set=\"11\" aria-pressed=\"true\">ווינדוס 11</button><button type=\"button\" data-set=\"10\" aria-pressed=\"false\">ווינדוס 10</button></div>\n    <small>לא בטוח? בווינדוס 11 כפתור ההתחלה נמצא באמצע שורת המשימות. בווינדוס 10 הוא בפינה.</small>\n  </div>\n\n  <!-- 1 -->\n  <section class=\"step\">\n    <div class=\"num\" aria-hidden=\"true\">1</div>\n    <div class=\"body\">\n      <h2>חילוץ הקובץ</h2>\n      <ol>\n        <li>מצא את קובץ ה-ZIP של התוסף (בדרך כלל בתיקייה <span class=\"say\">הורדות</span>).</li>\n        <li>לחץ עליו <b>בלחצן הימני</b> של העכבר ובחר <span class=\"say\">חילוץ הכל…</span></li>\n      </ol>\n      <div class=\"only11\"><figure><div class=\"shot\" style=\"max-width:730px\"><img src=\"data:image/jpeg;base64,\" width=\"730\" height=\"690\" alt=\"קליק ימני על קובץ ה-ZIP בווינדוס 11, והאפשרות חילוץ הכל מסומנת\"><span class=\"mk\" style=\"left:29.45%;top:49.28%;width:34.25%;height:4.93%\"><b>1</b></span></div><figcaption>ווינדוס 11: \"חילוץ הכל…\" נמצא באמצע התפריט.</figcaption></figure></div>\n      <div class=\"only10\"><figure><div class=\"shot\" style=\"max-width:820px\"><img src=\"data:image/jpeg;base64,\" width=\"820\" height=\"660\" alt=\"קליק ימני על קובץ ה-ZIP בווינדוס 10, והאפשרות חילוץ הכל מסומנת\"><span class=\"mk\" style=\"left:18.29%;top:30.61%;width:41.46%;height:4.55%\"><b>1</b></span></div><figcaption>ווינדוס 10: \"חילוץ הכל…\" נמצא בחלק העליון של התפריט.</figcaption></figure></div>\n      <ol start=\"3\">\n        <li>בחלון שנפתח לחץ <span class=\"say\">עיון…</span> ובחר <b>מקום קבוע</b> לתיקייה.</li>\n        <li>לחץ <span class=\"say\">חילוץ</span>.</li>\n      </ol>\n      <figure><div class=\"shot\" style=\"max-width:714px\"><img src=\"data:image/jpeg;base64,\" width=\"714\" height=\"596\" alt=\"חלון חילוץ תיקיות דחוסות, הכפתורים עיון וחילוץ מסומנים\"><span class=\"mk\" style=\"left:6.44%;top:30.87%;width:16.81%;height:6.38%\"><b>2</b></span><span class=\"mk\" style=\"left:14.57%;top:92.62%;width:13.45%;height:5.7%\"><b>3</b></span></div><figcaption>הנתיב שמופיע בחלון הוא ברירת המחדל. בעזרת \"עיון…\" אפשר לשנות אותו לכל מקום שתרצה.</figcaption></figure>\n      <div class=\"note warn\"><span>⚠️</span><span><b>חלץ למקום שלא נמחק.</b> כרום טוען את התוסף ישירות מהתיקייה הזו, ואם היא תימחק או תועבר, התוסף ייעלם. <b>אפשר לבחור כל מקום במחשב</b>, למשל תיקייה חדשה בשם \"תוספים\" בכונן C או במסמכים. רק לא מקום שאתה נוהג לנקות, כמו הורדות או שולחן העבודה.</span></div>\n    </div>\n  </section>\n\n  <!-- 2 -->\n  <section class=\"step\">\n    <div class=\"num\" aria-hidden=\"true\">2</div>\n    <div class=\"body\">\n      <h2>איזו תיקייה בדיוק טוענים</h2>\n      <p>כרום צריך את התיקייה שבתוכה נמצא הקובץ <code>manifest.json</code> <b>ישירות</b>. לעיתים קרובות החילוץ יוצר תיקייה בתוך תיקייה, אז כדאי לבדוק עכשיו:</p>\n      <ol>\n        <li>פתח את התיקייה שחילצת. אם יש בה רק תיקייה אחת, זו <b>התיקייה החיצונית</b>:</li>\n      </ol>\n      <div class=\"only11\"><figure><div class=\"shot\" style=\"max-width:980px\"><img src=\"data:image/jpeg;base64,\" width=\"980\" height=\"240\" alt=\"התיקייה החיצונית בווינדוס 11, ובתוכה רק תיקייה אחת מסומנת\"><span class=\"mk at-end\" style=\"left:1.84%;top:80.0%;width:75.92%;height:12.5%\"></span></div><figcaption>בתיקייה החיצונית יש רק תיקייה אחת. היכנס אליה.</figcaption></figure></div>\n      <div class=\"only10\"><figure><div class=\"shot\" style=\"max-width:1020px\"><img src=\"data:image/jpeg;base64,\" width=\"1020\" height=\"160\" alt=\"התיקייה החיצונית בווינדוס 10, ובתוכה רק תיקייה אחת מסומנת\"><span class=\"mk at-end\" style=\"left:3.33%;top:57.5%;width:73.53%;height:18.75%\"></span></div><figcaption>בתיקייה החיצונית יש רק תיקייה אחת. היכנס אליה.</figcaption></figure></div>\n      <ol start=\"2\">\n        <li>היכנס לתיקייה שבפנים. אם אתה רואה בה את <code>manifest</code> לצד עוד קבצים ותיקיות, <b>זו התיקייה שטוענים</b>.</li>\n      </ol>\n      <div class=\"only11\"><figure><div class=\"shot\" style=\"max-width:980px\"><img src=\"data:image/jpeg;base64,\" width=\"980\" height=\"420\" alt=\"התיקייה הפנימית בווינדוס 11, הקובץ manifest מסומן\"><span class=\"mk\" style=\"left:67.35%;top:63.57%;width:10.61%;height:7.14%\"></span></div><figcaption>הקובץ manifest נמצא כאן. זו התיקייה שטוענים בשלב 5.</figcaption></figure></div>\n      <div class=\"only10\"><figure><div class=\"shot\" style=\"max-width:1020px\"><img src=\"data:image/jpeg;base64,\" width=\"1020\" height=\"260\" alt=\"התיקייה הפנימית בווינדוס 10, הקובץ manifest.json מסומן\"><span class=\"mk\" style=\"left:61.76%;top:87.69%;width:12.75%;height:10.0%\"></span></div><figcaption>הקובץ manifest.json נמצא כאן. זו התיקייה שטוענים בשלב 5.</figcaption></figure></div>\n      <div class=\"note tip\"><span>💡</span><span>זכור: בשלב 5 תעמוד <b>בתיקייה החיצונית</b>, ותסמן בה את התיקייה הפנימית, זו שה-manifest נמצא בתוכה. ווינדוס יכול להסתיר את הסיומת ‎.json, אז ייתכן שתראה רק \"manifest\".</span></div>\n    </div>\n  </section>\n\n  <!-- 3 -->\n  <section class=\"step\">\n    <div class=\"num\" aria-hidden=\"true\">3</div>\n    <div class=\"body\">\n      <h2>פתיחת דף התוספים של כרום</h2>\n      <p>בכרום, לחץ על שורת הכתובת למעלה, הדבק את הכתובת הזו ולחץ <b>Enter</b>:</p>\n      <div class=\"copyrow\"><code id=\"extUrl\">chrome://extensions</code><button class=\"copybtn\" type=\"button\" data-copy=\"extUrl\">העתקה</button><span id=\"copyMsg\" role=\"status\" style=\"font-size:14px;color:var(--ok)\"></span></div>\n      <p style=\"color:var(--muted);font-size:15px\">אי אפשר ללחוץ על הכתובת הזו כקישור, כרום חוסם את זה. דרך נוספת, דרך התפריט:</p>\n      <figure><div class=\"shot\" style=\"max-width:780px\"><img src=\"data:image/jpeg;base64,\" width=\"780\" height=\"505\" alt=\"תפריט שלוש הנקודות של כרום, ובו תוספים ואז ניהול תוספים מסומנים\"><span class=\"mk at-end\" style=\"left:1.03%;top:0.99%;width:5.13%;height:7.52%\"><b>1</b></span><span class=\"mk\" style=\"left:33.33%;top:82.57%;width:28.21%;height:6.73%\"><b>2</b></span><span class=\"mk\" style=\"left:64.1%;top:82.57%;width:32.05%;height:6.73%\"><b>3</b></span></div><figcaption>שלוש הנקודות ⋮ בפינה, אחר כך \"תוספים\", ואז \"ניהול תוספים\".</figcaption></figure>\n    </div>\n  </section>\n\n  <!-- 4 -->\n  <section class=\"step\">\n    <div class=\"num\" aria-hidden=\"true\">4</div>\n    <div class=\"body\">\n      <h2>הפעלת \"מצב פיתוח\"</h2>\n      <p>בפינה השמאלית העליונה של הדף יש מתג בשם <span class=\"say\">מצב פיתוח</span>. לחץ עליו כך שיהפוך לכחול.</p>\n      <div class=\"pair\">\n        <figure><div class=\"shot\" style=\"max-width:640px\"><img src=\"data:image/jpeg;base64,\" width=\"640\" height=\"75\" alt=\"המתג מצב פיתוח כבוי\"><span class=\"mk at-end\" style=\"left:0.94%;top:24.0%;width:23.44%;height:48.0%\"></span></div><figcaption>לפני: המתג אפור (כבוי).</figcaption></figure>\n        <figure><div class=\"shot\" style=\"max-width:640px\"><img src=\"data:image/jpeg;base64,\" width=\"640\" height=\"75\" alt=\"המתג מצב פיתוח דלוק\"><span class=\"mk at-end\" style=\"left:0.94%;top:24.0%;width:23.44%;height:48.0%\"></span></div><figcaption>אחרי: המתג כחול (דלוק).</figcaption></figure>\n      </div>\n      <p>כדאי גם להדליק, באותו דף, את המתג <span class=\"say\">הצמדת תוספים חדשים לסרגל הכלים</span>. כך כל תוסף שתטען יופיע מיד ליד שורת הכתובת, ולא תצטרך את שלב 6.</p>\n      <figure><div class=\"shot\" style=\"max-width:1060px\"><img src=\"data:image/jpeg;base64,\" width=\"1060\" height=\"60\" alt=\"המתג הצמדת תוספים חדשים לסרגל הכלים, מעל רשימת התוספים\"><span class=\"mk at-end\" style=\"left:1.13%;top:21.67%;width:31.13%;height:60.0%\"></span></div><figcaption>המתג נמצא מעל רשימת התוספים, בצד שמאל של הכותרת \"כל התוספים\". בגרסאות כרום ישנות הוא לא קיים, וזה בסדר.</figcaption></figure>\n    </div>\n  </section>\n\n  <!-- 5 -->\n  <section class=\"step\">\n    <div class=\"num\" aria-hidden=\"true\">5</div>\n    <div class=\"body\">\n      <h2>טעינת התוסף</h2>\n      <ol>\n        <li>אחרי שמצב הפיתוח דלוק מופיעה שורת כפתורים. לחץ <span class=\"say\">טעינת פריט Unpacked</span>.</li>\n      </ol>\n      <figure><div class=\"shot\" style=\"max-width:680px\"><img src=\"data:image/jpeg;base64,\" width=\"680\" height=\"150\" alt=\"שורת הכפתורים של מצב הפיתוח, והכפתור טעינת פריט Unpacked מסומן\"><span class=\"mk\" style=\"left:65.29%;top:56.0%;width:30.88%;height:30.67%\"></span></div><figcaption>באנגלית הכפתור נקרא Load unpacked.</figcaption></figure>\n      <ol start=\"2\">\n        <li>בחלון שנפתח, הגע ל<b>תיקייה החיצונית</b> משלב 2. בשורת הנתיב למעלה תראה את השם שלה (מסומן 1).</li>\n        <li>סמן <b>בלחיצה אחת</b> את התיקייה הפנימית, זו שה-manifest בתוכה (מסומן 2). אל תיכנס אליה.</li>\n        <li>לחץ <span class=\"say\">בחר תיקייה</span> (מסומן 3).</li>\n      </ol>\n      <figure><div class=\"shot\" style=\"max-width:760px\"><img src=\"data:image/jpeg;base64,\" width=\"760\" height=\"290\" alt=\"חלון בחירת התיקייה: בשורת הנתיב התיקייה החיצונית, והתיקייה הפנימית מסומנת\"><span class=\"mk\" style=\"left:29.87%;top:12%;width:15.92%;height:8.34%\"><b>1</b></span><span class=\"mk\" style=\"left:22.7%;top:43.83%;width:74.08%;height:7.83%\"><b>2</b></span></div><figcaption>למעלה בשורת הנתיב: התיקייה החיצונית (1). ברשימה: התיקייה הפנימית, מסומנת בלחיצה אחת (2).</figcaption></figure><figure><div class=\"shot\" style=\"max-width:760px\"><img src=\"data:image/jpeg;base64,\" width=\"760\" height=\"70\" alt=\"תחתית החלון: הכפתור Select Folder מסומן\"><span class=\"mk\" style=\"left:72.11%;top:51.4%;width:13.55%;height:36.7%\"><b>3</b></span></div><figcaption>בתחתית החלון: \"בחר תיקייה\" (3). בצילום הכפתור באנגלית, Select Folder. אצלך הוא יכול להופיע בעברית.</figcaption></figure>\n      <div class=\"note tip\"><span>💡</span><span>בחלון הזה רואים רק תיקיות, לא קבצים, ולכן לא תראה כאן את manifest. זה תקין. נכנסת בטעות לתיקייה הפנימית? גם זה עובד: כשאתה בתוכה, פשוט לחץ \"בחר תיקייה\".</span></div>\n      <p>אחרי זה יופיע בדף כרטיס חדש עם שם התוסף. זה אומר שהוא מותקן.</p>\n    </div>\n  </section>\n\n  <!-- 6 -->\n  <section class=\"step\">\n    <div class=\"num\" aria-hidden=\"true\">6</div>\n    <div class=\"body\">\n      <h2>הצמדת התוסף לסרגל</h2>\n      <p>אם הדלקת בשלב 4 את \"הצמדת תוספים חדשים לסרגל הכלים\", התוסף כבר מוצמד ואפשר לדלג. אחרת, יש שתי דרכים:</p>\n      <h3>דרך א: סמל הפאזל 🧩 ליד שורת הכתובת</h3>\n      <ol>\n        <li>לחץ על סמל <b>הפאזל</b>.</li>\n        <li>ליד שם התוסף לחץ על <b>הנעץ</b> כך שיהפוך לכחול.</li>\n      </ol>\n      <figure><div class=\"shot\" style=\"max-width:660px\"><img src=\"data:image/jpeg;base64,\" width=\"660\" height=\"590\" alt=\"תפריט הפאזל של כרום ורשימת התוספים, סמל הפאזל והנעץ ליד אחד התוספים מסומנים\"><span class=\"mk\" style=\"left:35.15%;top:1.36%;width:6.97%;height:7.12%\"><b>1</b></span><span class=\"mk\" style=\"left:48.48%;top:53.56%;width:6.06%;height:5.76%\"><b>2</b></span></div><figcaption>נעץ כחול = מוצמד. נעץ אפור = לא מוצמד. (הצילום להדגמה בלבד – שאר התוספים ברשימה טושטשו.)</figcaption></figure>\n      <h3>דרך ב: אם אין אצלך סמל פאזל</h3>\n      <p>לפעמים סמל הפאזל מוסתר. במקרה כזה:</p>\n      <ol>\n        <li>חזור לדף <code>chrome://extensions</code>.</li>\n        <li>בכרטיס של התוסף לחץ <span class=\"say\">פרטים</span>.</li>\n        <li>גלול מטה והדלק את המתג <span class=\"say\">הצמדה לסרגל הכלים</span>.</li>\n      </ol>\n      <figure><div class=\"shot\" style=\"max-width:860px\"><img src=\"data:image/jpeg;base64,\" width=\"860\" height=\"160\" alt=\"דף הפרטים של תוסף, המתג הצמדה לסרגל הכלים מסומן\"><span class=\"mk at-end\" style=\"left:2.33%;top:50.0%;width:95.35%;height:25.0%\"></span></div><figcaption>המתג נמצא בדף הפרטים של התוסף, בערך באמצע הדף.</figcaption></figure>\n      <p>זהו. לחיצה על סמל התוסף בסרגל פותחת אותו.</p>\n    </div>\n  </section>\n\n  <section class=\"box\" aria-labelledby=\"upd\">\n    <h2 id=\"upd\">כשמקבלים גרסה חדשה של התוסף</h2>\n    <ol>\n      <li>חלץ את הקובץ החדש <b>לאותו מקום</b> שבו התוסף מותקן. כשווינדוס ישאל, בחר <span class=\"say\">החלף את הקבצים ביעד</span>.</li>\n      <li>פתח את <code>chrome://extensions</code> ולחץ על החץ המעגלי <b>⟳</b> בכרטיס של התוסף.</li>\n    </ol>\n    <figure><div class=\"shot\" style=\"max-width:504px\"><img src=\"data:image/jpeg;base64,\" width=\"504\" height=\"276\" alt=\"כרטיס של תוסף בדף התוספים, כפתור הטעינה מחדש המעגלי מסומן\"><span class=\"mk\" style=\"left:13.89%;top:76.81%;width:7.94%;height:13.77%\"></span></div><figcaption>החץ המעגלי מופיע רק כשמצב הפיתוח דלוק. מספר הגרסה בצילום (8.0.0) להדגמה בלבד – אצלך יופיע מספר הגרסה העדכני.</figcaption></figure>\n  </section>\n\n  <section class=\"box\" aria-labelledby=\"faq\">\n    <h2 id=\"faq\">אם משהו לא עובד</h2>\n    <div class=\"faq\">\n      <details><summary>כתוב \"חסר קובץ מניפסט\" (Manifest file is missing)</summary><p>נבחרה התיקייה החיצונית במקום הפנימית. חזור לשלב 5, היכנס לתיקייה החיצונית וסמן בה את התיקייה שה-manifest בתוכה.</p></details>\n      <details><summary>אין לי את הכפתור \"טעינת פריט Unpacked\"</summary><p>מצב הפיתוח כבוי. הדלק את המתג \"מצב פיתוח\" בשלב 4, והכפתור יופיע.</p></details>\n      <details><summary>כרום מציג הודעה על תוספים במצב פיתוח</summary><p>זו הודעה רגילה לכל תוסף שלא הותקן מהחנות. סגור אותה ב-✕ ואל תלחץ \"השבת\" או \"הסרה\". אם התוסף כבה, הדלק אותו שוב במתג שבכרטיס שלו.</p></details>\n      <details><summary>התוסף נעלם יום אחד</summary><p>כנראה התיקייה שלו נמחקה או הועברה. חלץ שוב את הקובץ למקום קבוע וחזור על שלב 5.</p></details>\n      <details><summary>אין לי אפשרות \"חילוץ הכל\" בתפריט</summary><p>אם מותקנת אצלך תוכנה כמו WinRAR או 7-Zip, היא עשויה להחליף את האפשרות. בחר בה \"חלץ אל…\" (Extract to…). בווינדוס 11 אפשר גם ללחוץ \"הצג אפשרויות נוספות\" בתחתית התפריט.</p></details>\n      <details><summary>לחצתי על סמל התוסף ולא קרה כלום</summary><p>בדוק ב-chrome://extensions שהמתג בכרטיס של התוסף דלוק ושאין בו כפתור \"שגיאות\" אדום. אם יש שגיאה, צלם אותה ושלח למי ששלח לך את התוסף.</p></details>\n    </div>\n  </section>\n\n  <p class=\"done\">אם נתקעת באחד השלבים, שלח צילום מסך למי ששלח לך את התוסף.</p>\n</div>\n\n<script>\n(function () {\n  var root = document.getElementById('root');\n  function setOs(v) {\n    root.setAttribute('data-os', v);\n    document.querySelectorAll('[data-set]').forEach(function (b) { b.setAttribute('aria-pressed', String(b.getAttribute('data-set') === v)); });\n    try { localStorage.setItem('dgGuideOs', v); } catch (e) { /* לא קריטי */ }\n  }\n  var saved = null;\n  try { saved = localStorage.getItem('dgGuideOs'); } catch (e) { saved = null; }\n  setOs(saved === '10' ? '10' : '11');\n  document.querySelectorAll('[data-set]').forEach(function (b) { b.addEventListener('click', function () { setOs(b.getAttribute('data-set')); }); });\n  document.querySelectorAll('[data-copy]').forEach(function (b) {\n    b.addEventListener('click', function () {\n      var el = document.getElementById(b.getAttribute('data-copy'));\n      var msg = document.getElementById('copyMsg');\n      var text = el.textContent;\n      var fallback = function () {\n        var r = document.createRange(); r.selectNodeContents(el);\n        var s = window.getSelection(); s.removeAllRanges(); s.addRange(r);\n        msg.textContent = 'הכתובת מסומנת. לחץ Ctrl+C';\n      };\n      if (navigator.clipboard && navigator.clipboard.writeText) {\n        navigator.clipboard.writeText(text).then(function () { msg.textContent = 'הועתק ✓'; }, fallback);\n      } else fallback();\n    });\n  });\n})();\n</script>\n\n<script>addEventListener(\"hashchange\",function(){if(location.hash!==\"#install\")location.reload()});</script>\n</body>\n</html>\n";
